const crypto = require('crypto');

const leadId = String(
  $json.odoo_lead_id ??
  $json.lead_id ??
  $('Fetch Lead Detail').item.json.odoo_lead_id
);

if (!leadId) {
  throw new Error('3.0.1.1: odoo_lead_id/lead_id is required');
}

const secret = $env.PROPOSAL_ACCEPT_HMAC_SECRET;
if (!secret) {
  throw new Error('3.0.1.1: PROPOSAL_ACCEPT_HMAC_SECRET is not configured');
}

// Token lifetime is intentionally short; change only if the master plan/business policy specifies another value.
const expiresAt = Math.floor(Date.now() / 1000) + (7 * 24 * 60 * 60);
const payload = `${leadId}.${expiresAt}`;

const signature = crypto
  .createHmac('sha256', secret)
  .update(payload, 'utf8')
  .digest('hex');

const acceptToken = `${payload}.${signature}`;

return [{
  json: {
    ...$json,
    accept_token: acceptToken,
    accept_token_lead_id: leadId,
    accept_token_expires_at: expiresAt
  }
}];
